def lpCutL (A : Set X) (hA : MeasurableSet A) : Lp 𝕜 p μ →L[𝕜] Lp 𝕜 p μ :=
  LinearMap.mkContinuous
    { toFun := lpCut A hA
      map_add' := lpCut_add A hA
      map_smul' := lpCut_smul A hA }
    1 (by intro f; simpa using norm_lpCut_le A hA f)

